svg.script:
const lang = new URLSearchParams(location.search).get('lang') === 'zh' ? 'zh' : 'en';
document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';

const header = lang === 'zh' ? {
  title: '蓝绿空间不是背景，它组织公共生活。',
  subtitle: 'BLUE-GREEN SPACE ORGANIZES PUBLIC LIFE.',
  protocol: '公共景观协议',
  state: '日常先行 · 试点有界 · 停机仍可用',
  stateSub: 'EVERYDAY FIRST · PILOT BOUNDED · FUNCTIONS REMAIN',
  caution: '概念设计目标 / 非法定绿地、水系或文保边界',
  cautionSub: 'DESIGN TARGET / NOT STATUTORY GREEN, WATER OR HERITAGE LIMITS'
} : {
  title: 'BLUE-GREEN SPACE ORGANIZES PUBLIC LIFE.',
  subtitle: '蓝绿空间不是背景，它组织公共生活。',
  protocol: 'CIVIC LANDSCAPE PROTOCOL',
  state: 'EVERYDAY FIRST · PILOT BOUNDED · FUNCTIONS REMAIN',
  stateSub: '日常先行 · 试点有界 · 停机仍可用',
  caution: 'DESIGN TARGET / NOT STATUTORY GREEN, WATER OR HERITAGE LIMITS',
  cautionSub: '概念设计目标 / 非法定绿地、水系或文保边界'
};

const nodes = document.querySelectorAll('text');
const zh = new Map(Object.entries({
  'JZOI 90 / FIG-07 / BLUE-GREEN + HERITAGE + PUBLIC REALM': 'JZOI 90 / FIG-07 / 蓝绿 + 遗产 + 公共空间',
  'QINGHE RAIN EDGE / 清河雨洪生态边缘': '清河雨洪生态边缘 / QINGHE RAIN EDGE',
  'XIAOYUEHE RELATION / 小月河关系 · 需专业复核': '小月河关系 / XIAOYUEHE · 须专业复核',
  'JINGZHANG HERITAGE + PUBLIC SEQUENCE': '京张遗产与公共序列',
  '京张遗产与公共序列 · 可逆标识 / 不推定文保控制线': 'JINGZHANG HERITAGE + PUBLIC SEQUENCE · REVERSIBLE MARKERS / NO HERITAGE CONTROL-LINE CLAIM',
  'NORTH RAIN STITCH / 北部雨洪缝合': '北部雨洪缝合 / NORTH RAIN STITCH',
  'CENTRAL RAIN STITCH / 中部雨洪缝合': '中部雨洪缝合 / CENTRAL RAIN STITCH',
  'SOUTH RAIN STITCH / 南部雨洪缝合': '南部雨洪缝合 / SOUTH RAIN STITCH',
  'ZZY / SAFETY ECOLOGY BUFFER': 'ZZY / 安全生态缓冲',
  '观察湿地 · 公共绕行 · 测试专属距离待安全论证': 'OBSERVATION WETLAND · PUBLIC BYPASS · TEST-SPECIFIC DISTANCE REQUIRES SAFETY CASE',
  'ORG / COMMONS GARDEN': 'ORG / 公地花园',
  '四向通行 · 遮荫工作面 · 邻里停留 · 人工公地服务': 'FOUR-WAY PASSAGE · SHADE WORK SURFACE · NEIGHBORHOOD STAY · STAFFED COMMONS SERVICE',
  'DZS / CIVIC RAIN ROOM': 'DZS / 公共雨洪空间',
  '雨洪公共空间 · 固定导视 · 遮荫等候 · 文化展示': 'RAINWATER PUBLIC ROOM · FIXED WAYFINDING · SHADED WAITING · CULTURAL DISPLAY',
  'RELATIVE CONCEPT GEOMETRY ONLY · NO VERIFIED FLOOD PERFORMANCE, CAPACITY, SURVEYED LEVELS OR STATUTORY HERITAGE LIMITS.': '仅为相对概念几何 · 不主张已验证雨洪绩效、容量、实测高程或法定文保边界。',
  'ONE LANDSCAPE / FOUR CIVIC DUTIES': '一套景观 / 四项公共职责',
  '01 / RAINWATER + ECOLOGY INTENT': '01 / 雨洪 + 生态意向',
  '雨洪调蓄意向 · 生境边缘 · 水系关系待专业资料': 'RAINWATER INTENT · HABITAT EDGE · WATER RELATION REQUIRES PROFESSIONAL EVIDENCE',
  '02 / SHADE + REST + PUBLIC STAY': '02 / 遮荫 + 休息 + 公共停留',
  '遮荫 · 休息 · 安静等候 · 日常公共停留': 'SHADE · REST · QUIET WAITING · EVERYDAY PUBLIC STAY',
  '03 / HERITAGE + CULTURAL DISPLAY': '03 / 遗产 + 文化展示',
  '可逆标识 · 公共序列 · 不推定遗产清单与控制区': 'REVERSIBLE MARKERS · PUBLIC SEQUENCE · NO HERITAGE INVENTORY OR CONTROL-ZONE CLAIM',
  '04 / SAFETY + TEST SEPARATION': '04 / 安全 + 测试分隔',
  '测试边界附加于公共基底 · 公共路径不得被占用': 'TEST BOUNDARY ADDED TO PUBLIC BASE · PUBLIC PATHS MUST NOT BE OCCUPIED',
  'THREE ENDPOINT LANDSCAPE ROOMS': '三个端点景观空间',
  'ZZY / OBSERVATION WETLAND': 'ZZY / 观察湿地',
  'SAFETY ECOLOGY BUFFER · PUBLIC BYPASS': '安全生态缓冲 · 公共绕行',
  'ORG / COMMONS GARDEN': 'ORG / 公地花园',
  'POROUS PASSAGES · SHADE · PUBLIC WORK SURFACE': '多孔通道 · 遮荫 · 公共工作面',
  'DZS / CIVIC RAIN ROOM': 'DZS / 公共雨洪空间',
  'RAINWATER PUBLIC ROOM · WAITING · CULTURAL DISPLAY': '雨洪公共空间 · 等候 · 文化展示',
  'EVIDENCE BOUNDARY / 证据边界': '证据边界 / EVIDENCE BOUNDARY',
  'ALL FEATURES ARE CONCEPT DESIGN TARGETS; RECALCULATE AFTER SURVEY,': '所有特征均为概念设计目标；须在测绘、',
  'WATER, LANDSCAPE, HERITAGE, ACCESSIBILITY + OPERATIONS REVIEW.': '水务、景观、遗产、无障碍与运营复核后重算。',
  'BASE FUNCTIONS REMAIN / 基础公共与生态功能持续': '基础公共与生态功能持续 / BASE FUNCTIONS REMAIN',
  '同一空间基底，不同运行状态；不主张相同体验或已验证绩效。': 'SAME SPATIAL BASE, DIFFERENT OPERATING STATES; NO CLAIM OF IDENTICAL EXPERIENCE OR VERIFIED PERFORMANCE.',
  'EVERYDAY / 日常状态': '日常状态 / EVERYDAY',
  'WALK · SHADE · REST · HERITAGE · PUBLIC STAY · RAINWATER INTENT': '步行 · 遮荫 · 休息 · 遗产 · 公共停留 · 雨洪意向',
  'PILOT ACTIVE / 试点运行': '试点运行 / PILOT ACTIVE',
  'SAME PUBLIC BASE + BOUNDED TEST SEPARATION + STAFFED STATUS': '同一公共基底 + 有界测试分隔 + 人工状态说明',
  'DIGITAL OFF / 数字系统停用': '数字系统停用 / DIGITAL OFF',
  'PUBLIC + ECOLOGICAL FUNCTIONS REMAIN · FIXED SIGNS + STAFFED HELP': '公共 + 生态功能持续 · 固定导视 + 人工帮助',
  'FIG-07 V3.4 REVIEW PREVIEW · CONCEPT / PROVISIONAL / NOT STATUTORY · NO VERIFIED FLOOD PERFORMANCE OR HERITAGE-CONTROL CLAIM.': 'FIG-07 V3.4 · 蓝绿公共空间 · 概念 / 临时 / 非法定 · 不主张已验证雨洪绩效或文保控制线。',
  'JINGZHANG OPEN INTERFACE': '京张开放接口'
}));

const en = new Map(Object.entries({
  '蓝绿空间不是背景，它组织公共生活。': 'RAINWATER ECOLOGY · HERITAGE SEQUENCE · PUBLIC STAY · BOUNDED PILOT',
  '日常先行 · 试点有界 · 停机仍可用': 'PUBLIC BASE FUNCTIONS REMAIN IN EVERY OPERATING STATE',
  '概念设计目标 / 非法定绿地、水系或文保边界': 'CONCEPT / PROVISIONAL / NON-STATUTORY',
  'QINGHE RAIN EDGE / 清河雨洪生态边缘': 'QINGHE RAINWATER ECOLOGY EDGE',
  'XIAOYUEHE RELATION / 小月河关系 · 需专业复核': 'XIAOYUEHE RELATION · PROFESSIONAL REVIEW REQUIRED',
  '京张遗产与公共序列 · 可逆标识 / 不推定文保控制线': 'REVERSIBLE MARKERS · NO HERITAGE CONTROL-LINE CLAIM',
  'NORTH RAIN STITCH / 北部雨洪缝合': 'NORTH RAIN STITCH',
  'CENTRAL RAIN STITCH / 中部雨洪缝合': 'CENTRAL RAIN STITCH',
  'SOUTH RAIN STITCH / 南部雨洪缝合': 'SOUTH RAIN STITCH',
  '观察湿地 · 公共绕行 · 测试专属距离待安全论证': 'OBSERVATION WETLAND · PUBLIC BYPASS · TEST DISTANCE REQUIRES SAFETY CASE',
  '四向通行 · 遮荫工作面 · 邻里停留 · 人工公地服务': 'POROUS PASSAGE · SHADE WORK SURFACE · NEIGHBORHOOD STAY · STAFFED SERVICE',
  '雨洪公共空间 · 固定导视 · 遮荫等候 · 文化展示': 'RAINWATER PUBLIC ROOM · FIXED WAYFINDING · SHADED WAITING · CULTURAL DISPLAY',
  '雨洪调蓄意向 · 生境边缘 · 水系关系待专业资料': 'RAINWATER INTENT · HABITAT EDGE · WATER RELATION REQUIRES PROFESSIONAL EVIDENCE',
  '遮荫 · 休息 · 安静等候 · 日常公共停留': 'SHADE · REST · QUIET WAITING · EVERYDAY PUBLIC STAY',
  '可逆标识 · 公共序列 · 不推定遗产清单与控制区': 'REVERSIBLE MARKERS · PUBLIC SEQUENCE · NO HERITAGE INVENTORY OR CONTROL-ZONE CLAIM',
  '测试边界附加于公共基底 · 公共路径不得被占用': 'TEST BOUNDARY ADDED TO PUBLIC BASE · PUBLIC PATHS MUST REMAIN OPEN',
  'EVIDENCE BOUNDARY / 证据边界': 'EVIDENCE BOUNDARY',
  'BASE FUNCTIONS REMAIN / 基础公共与生态功能持续': 'BASE FUNCTIONS REMAIN',
  '同一空间基底，不同运行状态；不主张相同体验或已验证绩效。': 'SAME SPATIAL BASE, DIFFERENT OPERATING STATES; NO CLAIM OF IDENTICAL EXPERIENCE OR VERIFIED PERFORMANCE.',
  'EVERYDAY / 日常状态': 'EVERYDAY',
  'PILOT ACTIVE / 试点运行': 'PILOT ACTIVE',
  'DIGITAL OFF / 数字系统停用': 'DIGITAL OFF'
}));

const mainTexts = {
  title: header.title,
  subtitle: header.subtitle,
  protocol: header.protocol,
  state: header.state,
  stateSub: header.stateSub,
  caution: header.caution,
  cautionSub: header.cautionSub
};
const mainNodes = [...nodes];
const first = document.getElementById('main-title');
if (first) first.textContent = mainTexts.title;
const subtitle = document.getElementById('main-subtitle');
if (subtitle && subtitle !== first) subtitle.textContent = mainTexts.subtitle;
const protocol = mainNodes.find(node => node.textContent.trim() === 'CIVIC LANDSCAPE PROTOCOL');
const state = mainNodes.find(node => node.textContent.trim() === '日常先行 · 试点有界 · 停机仍可用');
const stateSub = mainNodes.find(node => node.textContent.trim() === 'EVERYDAY FIRST · PILOT BOUNDED · FUNCTIONS REMAIN');
const caution = mainNodes.find(node => node.textContent.trim() === '概念设计目标 / 非法定绿地、水系或文保边界');
const cautionSub = mainNodes.find(node => node.textContent.trim() === 'DESIGN TARGET / NOT STATUTORY GREEN, WATER OR HERITAGE LIMITS');
if (protocol) protocol.textContent = mainTexts.protocol;
if (state) state.textContent = mainTexts.state;
if (stateSub) stateSub.textContent = mainTexts.stateSub;
if (caution) caution.textContent = mainTexts.caution;
if (cautionSub) cautionSub.textContent = mainTexts.cautionSub;
if (lang === 'en') {
  first.setAttribute('font-size', '54');
  state.setAttribute('font-size', '19');
  stateSub.setAttribute('font-size', '12');
  nodes.forEach(node => {
    const localized = en.get(node.textContent.trim());
    if (localized) node.textContent = localized;
  });
  [...nodes].find(node => node.textContent.trim().startsWith('REVERSIBLE MARKERS · PUBLIC SEQUENCE'))?.setAttribute('font-size', '11');
  [...nodes].find(node => node.textContent.trim().startsWith('RAINWATER INTENT · HABITAT EDGE'))?.setAttribute('font-size', '11');
} else {
  first.setAttribute('font-size', '70');
}

if (lang === 'zh') {
  nodes.forEach(node => {
    const localized = zh.get(node.textContent.trim());
    if (localized) node.textContent = localized;
  });
}
document.querySelector('svg').setAttribute('aria-label', lang === 'zh'
  ? '蓝绿空间组织公共生活：雨洪生态、遗产序列、公共停留与有界测试分隔'
  : 'Blue-green space organizes public life through rainwater ecology, heritage sequence, public stay, and bounded test separation');
